import{_ as t,o as d,c as a,a0 as o}from"./chunks/framework.CNXp-E7Q.js";const u=JSON.parse('{"title":"Architecture","description":"","frontmatter":{},"headers":[],"relativePath":"explanation/architecture.md","filePath":"explanation/architecture.md"}'),n={name:"explanation/architecture.md"};function r(s,e,c,i,l,p){return d(),a("div",null,[...e[0]||(e[0]=[o(`<h1 id="architecture" tabindex="-1">Architecture <a class="header-anchor" href="#architecture" aria-label="Permalink to &quot;Architecture&quot;">​</a></h1><p>bupha is a port/adapter monorepo: <code>bupha-core</code> owns the domain and knows nothing about GitHub, dagger, or cloudflared; every integration is an impl crate behind a port.</p><h2 id="crate-map" tabindex="-1">Crate map <a class="header-anchor" href="#crate-map" aria-label="Permalink to &quot;Crate map&quot;">​</a></h2><table tabindex="0"><thead><tr><th>crate</th><th>layer</th><th>role</th></tr></thead><tbody><tr><td><code>bupha-core</code></td><td>domain</td><td><code>bupha.toml</code> types, <code>Queue</code>, <code>Trigger</code> + <code>StatusSink</code> ports, replay <code>Seen</code>, sha validation</td></tr><tr><td><code>bupha-runner</code></td><td>port</td><td><code>Runner</code> trait — spawn/kill a pipeline child</td></tr><tr><td><code>bupha-tunnel</code></td><td>port</td><td><code>Tunnel</code> trait — expose the listener</td></tr><tr><td><code>bupha-github</code></td><td>impl</td><td>webhook verify + parse (Trigger), commit statuses (StatusSink), hook register/delete</td></tr><tr><td><code>bupha-script</code></td><td>impl</td><td><code>bash -c &lt;cmd&gt;</code> in the worktree — zero containers</td></tr><tr><td><code>bupha-dagger</code></td><td>impl</td><td><code>dagger call</code> into the consumer repo&#39;s module</td></tr><tr><td><code>bupha-cloudflared</code></td><td>impl</td><td>cloudflared child (quick + named tunnels)</td></tr><tr><td><code>bupha-deploy</code></td><td>impl</td><td>systemd unit, env file, publish order, probe</td></tr><tr><td><code>bupha</code> (cli)</td><td>binary</td><td>wires it all: <code>watch</code>, <code>run</code>, <code>doctor</code>, <code>init</code>, <code>deploy</code>, <code>destroy</code></td></tr></tbody></table><p><code>modules/dagger/</code> (Python SDK) is the shared pipeline module <code>bupha init</code> installs into consumer repos — pinned to a sha.</p><h2 id="request-flow" tabindex="-1">Request flow <a class="header-anchor" href="#request-flow" aria-label="Permalink to &quot;Request flow&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>POST /hook</span></span>
<span class="line"><span>  → 1. path check (404 otherwise)</span></span>
<span class="line"><span>  → 2. read body (≤ 2 MiB)</span></span>
<span class="line"><span>  → 3. HMAC verify — sha256, constant-time</span></span>
<span class="line"><span>  → 4. dedup X-GitHub-Delivery (bounded 10k ring)</span></span>
<span class="line"><span>  → 5. parse — skip deletes/zero-sha; reject non-hex sha</span></span>
<span class="line"><span>  → 6. route — repository.full_name → watched [[repos]] entry;</span></span>
<span class="line"><span>       git_ref must equal repo.branch</span></span>
<span class="line"><span>  → 7. enqueue — per-repo queue; atomic queue.json persist</span></span>
<span class="line"><span>  → 8. one global worker — git fetch, detached worktree</span></span>
<span class="line"><span>       at &lt;base&gt;-&lt;repo&gt;-&lt;sha12&gt;</span></span>
<span class="line"><span>  → 9. spawn runner child (token via env:// name, never argv)</span></span>
<span class="line"><span>  → 10. status — pending → success/error; superseded and</span></span>
<span class="line"><span>        cancelled shas get honest error statuses</span></span></code></pre></div><h2 id="queue-semantics" tabindex="-1">Queue semantics <a class="header-anchor" href="#queue-semantics" aria-label="Permalink to &quot;Queue semantics&quot;">​</a></h2><table tabindex="0"><thead><tr><th>policy</th><th>pending</th><th>on new push</th><th>use for</th></tr></thead><tbody><tr><td><code>latest</code> (default)</td><td>1 sha</td><td>supersedes pending; <code>cancel_running</code> may kill in-flight</td><td>CI gates</td></tr><tr><td><code>all</code></td><td>bounded FIFO (32)</td><td>appends; oldest evicted past cap; <code>cancel_running</code> rejected at load — it would drop a promised commit</td><td>releases</td></tr></tbody></table><p>Persistence: accepted work writes <code>queue.json</code> via tmp+rename inside <code>worktree.base</code>; on restart the interrupted <code>running</code> sha is re-queued at the front.</p><p>One <strong>global worker</strong> serializes runs across all repos — a second push queues behind the in-flight job. Deliberate (one box, bounded resource use), not a hang: <code>journalctl --user -u bupha-watch</code> shows the queue moving.</p><h2 id="security-model" tabindex="-1">Security model <a class="header-anchor" href="#security-model" aria-label="Permalink to &quot;Security model&quot;">​</a></h2><ul><li>mandatory HMAC (constant-time compare) — unauthenticated payloads never reach the queue</li><li>body cap, delivery-id replay dedup, hex-sha validation before the value touches paths or status URLs</li><li>webhook takeover is exact-URL only; hook API calls are timed out</li><li>config names secrets (<code>secret_env</code>/<code>token_env</code>) — values resolve env → OS keyring → <code>~/.config/bupha/env</code> (0600); the runner gets the token through its own mechanism (<code>env://</code> for dagger)</li></ul><h2 id="extending" tabindex="-1">Extending <a class="header-anchor" href="#extending" aria-label="Permalink to &quot;Extending&quot;">​</a></h2><table tabindex="0"><thead><tr><th>to add…</th><th>write…</th><th>core changes?</th></tr></thead><tbody><tr><td>forge (gitea/gitlab)</td><td><code>Trigger</code> + <code>StatusSink</code> impl crate</td><td>no</td></tr><tr><td>pipeline backend</td><td><code>Runner</code> impl crate</td><td>no</td></tr><tr><td>ingress (fly/tailscale)</td><td><code>Tunnel</code> impl crate</td><td>no</td></tr></tbody></table><h2 id="planned-seams-0-2" tabindex="-1">Planned seams (0.2+) <a class="header-anchor" href="#planned-seams-0-2" aria-label="Permalink to &quot;Planned seams (0.2+)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>coupling</th><th>where</th><th>planned port</th></tr></thead><tbody><tr><td>OS service mgmt</td><td><code>bupha-deploy</code> (systemd, df, journalctl)</td><td><code>Service</code> — launchd/Windows</td></tr><tr><td>secret storage</td><td><code>secret()</code> — secret-tool</td><td><code>keyring</code> crate (macOS/Win)</td></tr><tr><td>config path</td><td><code>~/.config/bupha</code> (XDG)</td><td><code>dirs</code> crate</td></tr><tr><td>VCS ops</td><td><code>git()</code>/<code>repo_sync</code> shell to git</td><td><code>Vcs</code> trait → <code>GitVcs</code> (jj/hg)</td></tr><tr><td>queue persistence</td><td><code>queue.json</code> in cli</td><td><code>QueueStore</code> — SQLite/remote for distributed runners</td></tr></tbody></table>`,17)])])}const b=t(n,[["render",r]]);export{u as __pageData,b as default};
